-- Этап B, пачка 5/7 — сводка отзывов на основе веб-поиска.

update public.institutions set
  feedback_summary_student = 'СПбГИКиТ стабильно лидирует среди творческих вузов, выпускники становятся лауреатами кинофестивалей, обучение сочетает теорию и обширную сценическую практику. Заметная критика — несбалансированная нагрузка (второстепенные предметы отнимают больше времени, чем профильные), грубость приёмной комиссии, у части преподавателей отмечается низкая мотивация. Отдельно — недовольство соотношением цены и качества на платном отделении (390 000+ руб/год).',
  feedback_positive_highlights = '{"лидер среди творческих вузов по конкурсам и фестивалям","насыщенная сценическая практика"}',
  feedback_negative_highlights = '{"несбалансированная нагрузка по непрофильным предметам","грубость приёмной комиссии","недовольство соотношением цены и качества на платном"}',
  feedback_based_on_count = 5, feedback_generated_at = now(), updated_at = now()
where name = 'Санкт-Петербургский государственный институт кино и телевидения' and city = 'Санкт-Петербург';

update public.institutions set
  feedback_summary_student = 'Небольшой камерный вуз с семейной атмосферой: практикующие преподаватели, интересные семинары по психологии/конфликтологии, возможность публикаций. Заметная критика — часть отзывов описывает хамское отношение деканата к студентам, недостаток практики (в основном классическая начитка материала), ограниченный доступ к известным базам практики из-за небольшого размера вуза.',
  feedback_positive_highlights = '{"камерная, "семейная" атмосфера","практикующие преподаватели по психологии","возможность публикации студенческих работ"}',
  feedback_negative_highlights = '{"недостаток практики, упор на теорию","ограниченный доступ к сильным базам практики","жалобы на отношение деканата"}',
