update public.institutions set
  feedback_summary_student = 'Одна из самых знаменитых консерваторий мира. Отзывы отмечают хороший фундамент знаний и компетентных педагогов, но подчёркивают: результат сильно зависит от выбора конкретного преподавателя-наставника — «немногие действительно умеют учить». Отдельная жалоба — многолетний ремонт здания и отсутствие доступа к основному концертному залу у нескольких выпусков подряд.',
  feedback_positive_highlights = '{"мировая репутация и уровень образования","сильные педагоги при правильном выборе наставника"}',
  feedback_negative_highlights = '{"результат сильно зависит от конкретного педагога","многолетний ремонт, недоступность основного концертного зала"}',
  feedback_based_on_count = 3, feedback_generated_at = now(), updated_at = now()
