update public.institutions set
  feedback_summary_student = '«Корабелка» — единственный в России вуз, готовящий морских инженеров, подготовка подтверждена международными экспертами (Институт морских инженеров, Лондон). Насыщенная программа (3D-моделирование, автоматизированные системы), гарантированное трудоустройство через партнёров-предприятия. Заметная критика — состояние ряда корпусов (без ремонта с советских времён), устаревшие общежития и учебники по некоторым курсам.',
  feedback_positive_highlights = '{"единственный в РФ вуз морского инжиниринга, признание за рубежом","насыщенная и современная программа по ряду направлений","гарантированное трудоустройство через партнёров"}',
  feedback_negative_highlights = '{"состояние ряда корпусов без ремонта с советских времён","устаревшие общежития и учебники по отдельным курсам"}',
  feedback_based_on_count = 30, feedback_generated_at = now(), updated_at = now()
where name = 'Санкт-Петербургский государственный морской технический университет' and city = 'Санкт-Петербург';

